arguments:
$ErrorActionPreference = 'SilentlyContinue'
$since = [datetime]'2026-09-04T16:15:00'
'=== PROCESS ==='
Get-Process -Name Cinebench | Select-Object Id,SessionId,StartTime,CPU,WorkingSet64,MainWindowTitle,Path | Format-List
'=== MAXON_DIRECTORIES ==='
$roots = @('C:\Users\Song\AppData\Roaming\MAXON','C:\Users\Song\AppData\Local\MAXON','C:\Users\Song\Documents\MAXON','C:\Assets\Cinebench2026')
foreach ($root in $roots) {
 if (Test-Path -LiteralPath $root) {
  Write-Output ('ROOT=' + $root)
  Get-ChildItem -LiteralPath $root -Directory | Select-Object Name,LastWriteTime,FullName | Format-List
 }
}
'=== RECENT_FILES ==='
$recent = @()
foreach ($root in $roots) {
 if (Test-Path -LiteralPath $root) {
  $recent += Get-ChildItem -LiteralPath $root -Recurse -File | Where-Object { $_.LastWriteTime -ge $since }
 }
}
$recent | Sort-Object LastWriteTime -Descending | Select-Object -First 150 Name,Extension,Length,CreationTime,LastWriteTime,FullName | Format-List
'=== RESULT_NAME_CANDIDATES ==='
foreach ($root in $roots) {
 if (Test-Path -LiteralPath $root) {
  Get-ChildItem -LiteralPath $root -Recurse -File | Where-Object { $_.Name -match 'score|result|ranking|benchmark|cinebench|prefs|history' } | Sort-Object LastWriteTime -Descending | Select-Object -First 100 Name,Length,LastWriteTime,FullName | Format-List
 }
}
'=== RECENT_TEXT_CONTENT ==='
foreach ($file in ($recent | Where-Object { $_.Length -le 1048576 -and $_.Extension -match '^\.(txt|log|json|xml|csv|ini|cfg|prf)$' } | Select-Object -First 40)) {
 Write-Output ('FILE=' + $file.FullName)
 Get-Content -LiteralPath $file.FullName -Tail 120
}
exit 0
